// ───────────────────────── src/core/math.js ─────────────────────────
/**
 * Pure math helpers. No platform dependencies (works in React Native / Node / browser).
 */

const clamp = (value, min, max) => Math.min(max, Math.max(min, value))

const logit = (p) => Math.log(p / (1 - p))

const sigmoid = (x) => 1 / (1 + Math.exp(-x))

/** Linear ramp: 0 at x0, 1 at x1, clamped. */
const ramp = (x, x0, x1) => clamp((x - x0) / (x1 - x0), 0, 1)

/**
 * Piecewise-linear interpolation over sorted [x, y] points.
 * Values outside the range are clamped to the first / last y.
 */
function interpolate(points, x) {
  if (x <= points[0][0]) return points[0][1]
  const last = points[points.length - 1]
  if (x >= last[0]) return last[1]
  for (let i = 1; i < points.length; i++) {
    const [x1, y1] = points[i]
    if (x <= x1) {
      const [x0, y0] = points[i - 1]
      const t = (x - x0) / (x1 - x0)
      return y0 + t * (y1 - y0)
    }
  }
  return last[1]
}

/** Interpolates probability knots in logit space; returns the LOGIT. Smooth, no kinks in P space. */
function interpolateLogit(points, x) {
  const pts = points.map(([px, py]) => [px, logit(clamp(py, 0.005, 0.995))])
  return interpolate(pts, x)
}

/** Soft squash into [3%, 97%]: monotone, never produces exact ties like a hard clamp would. */
const squash = (l) => 0.03 + 0.94 * sigmoid(l)

/** Deterministic 32-bit FNV-1a hash of a string. */
function hashString(str) {
  let h = 2166136261
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

const roundTo = (value, step = 1) => Math.round(value / step) * step

const toPercent = (p) => Math.round(p * 100)

/** "+5", "−5" (typographic minus) or "±0". */
const formatSignedPoints = (n) => (n > 0 ? `+${n}` : n < 0 ? `−${Math.abs(n)}` : '±0')

/** "+5 punti", "−1 punto", "±0 punti". */
const formatPoints = (n) => `${formatSignedPoints(n)} ${Math.abs(n) === 1 ? 'punto' : 'punti'}`

// ───────────────────────── src/core/dates.js ─────────────────────────
/**
 * Date helpers with Italian formatting. Deliberately avoids Intl so that the
 * output is identical on web, Node and React Native (Hermes). All day
 * arithmetic goes through setDate/setHours on local fields, which is DST-safe.
 */

const WEEKDAYS_IT = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato']
const WEEKDAYS_SHORT_IT = ['dom', 'lun', 'mar', 'mer', 'gio', 'ven', 'sab']
const MONTHS_IT = [
  'gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno',
  'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre',
]

const pad2 = (n) => String(n).padStart(2, '0')

const capitalize = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s)

const startOfDay = (date) => {
  const d = new Date(date)
  d.setHours(0, 0, 0, 0)
  return d
}

const addDays = (date, days) => {
  const d = new Date(date)
  d.setDate(d.getDate() + days)
  return d
}

const addMinutes = (date, minutes) => new Date(date.getTime() + minutes * 60_000)

/** Returns a copy of `date` with the local time set to hours:minutes. */
const atTime = (date, hours, minutes = 0) => {
  const d = new Date(date)
  d.setHours(hours, minutes, 0, 0)
  return d
}

const minutesOfDay = (date) => date.getHours() * 60 + date.getMinutes()

const daysInMonth = (date) => new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate()

/** Whole calendar days between the two dates (ignores the time of day; DST-safe thanks to rounding). */
const calendarDaysBetween = (from, to) => {
  const a = startOfDay(from)
  const b = startOfDay(to)
  return Math.round((b - a) / 86_400_000)
}

const isSameDay = (a, b) => calendarDaysBetween(a, b) === 0

const formatTime = (date) => `${pad2(date.getHours())}:${pad2(date.getMinutes())}`

const formatMinutes = (minutes) => `${pad2(Math.floor(minutes / 60) % 24)}:${pad2(minutes % 60)}`

/** "12:30–14:00" */
const formatRange = (from, to) => `${formatMinutes(from)}–${formatMinutes(to)}`

/** "domenica 5 ottobre" (+ " 2027" when the year differs from `reference`). */
const formatLongDate = (date, reference) => {
  const base = `${WEEKDAYS_IT[date.getDay()]} ${date.getDate()} ${MONTHS_IT[date.getMonth()]}`
  return reference && reference.getFullYear() !== date.getFullYear() ? `${base} ${date.getFullYear()}` : base
}

/** "oggi" | "domani" | "tra 5 giorni" relative to `now`. */
const formatRelativeDay = (date, now) => {
  const days = calendarDaysBetween(now, date)
  if (days <= 0) return 'oggi'
  if (days === 1) return 'domani'
  return `tra ${days} giorni`
}

/** [1,2,3,4,5] → "lun–ven", [0,6] → "sab e dom", [0] → "dom", all → "tutti i giorni". */
function formatDayList(days) {
  const sorted = [...new Set(days)].sort((a, b) => a - b)
  if (sorted.length === 7) return 'tutti i giorni'
  if (sorted.length === 1) return WEEKDAYS_SHORT_IT[sorted[0]]
  if (sorted.length === 2 && sorted[0] === 0 && sorted[1] === 6) return 'sab e dom'
  const contiguous = sorted.every((d, i) => i === 0 || d === sorted[i - 1] + 1)
  if (contiguous) return `${WEEKDAYS_SHORT_IT[sorted[0]]}–${WEEKDAYS_SHORT_IT[sorted[sorted.length - 1]]}`
  return sorted.map((d) => WEEKDAYS_SHORT_IT[d]).join(', ')
}

/** Rounds a date UP to the next multiple of `stepMinutes`. */
const ceilToMinutes = (date, stepMinutes = 5) => {
  const d = new Date(date)
  d.setSeconds(0, 0)
  const rem = d.getMinutes() % stepMinutes
  if (rem !== 0) d.setMinutes(d.getMinutes() + (stepMinutes - rem))
  return d
}

/** Easter Sunday (Gregorian, Meeus/Jones/Butcher). */
function easterSunday(year) {
  const a = year % 19
  const b = Math.floor(year / 100)
  const c = year % 100
  const d = Math.floor(b / 4)
  const e = b % 4
  const f = Math.floor((b + 8) / 25)
  const g = Math.floor((b - f + 1) / 3)
  const h = (19 * a + b - d - g + 15) % 30
  const i = Math.floor(c / 4)
  const k = c % 4
  const l = (32 + 2 * e + 2 * i - h - k) % 7
  const m = Math.floor((a + 11 * h + 22 * l) / 451)
  const month = Math.floor((h + l - 7 * m + 114) / 31) - 1
  const day = ((h + l - 7 * m + 114) % 31) + 1
  return new Date(year, month, day)
}

const FIXED_HOLIDAYS_IT = new Set(['1-1', '1-6', '4-25', '5-1', '6-2', '8-15', '11-1', '12-8', '12-25', '12-26'])

/** Italian national public holidays (fixed dates + Easter Monday). */
function isItalianHoliday(date) {
  if (FIXED_HOLIDAYS_IT.has(`${date.getMonth() + 1}-${date.getDate()}`)) return true
  return isSameDay(date, addDays(easterSunday(date.getFullYear()), 1))
}

/** UTC offset of Europe/Rome in minutes for the given instant (EU DST rule: last Sunday of March → last Sunday of October, 01:00 UTC). */
function romeOffsetMinutes(date) {
  const year = date.getUTCFullYear()
  const lastSundayUtc = (month) => {
    const d = new Date(Date.UTC(year, month + 1, 0, 1, 0, 0, 0))
    d.setUTCDate(d.getUTCDate() - d.getUTCDay())
    return d
  }
  const start = lastSundayUtc(2)
  const end = lastSundayUtc(9)
  return date >= start && date < end ? 120 : 60
}

const deviceOffsetMinutes = (date) => -date.getTimezoneOffset()

